#!/usr/bin/env node
/**
 * Builds the MARS handler files of the winter pages and the planner from
 * apps/api/handlers + apps/api/lib.
 *
 *   node tools/build-mars-api.mjs           write apps/api/v2/... and apps/api/events/...
 *   node tools/build-mars-api.mjs --check   exit 2 if a generated file is stale
 *
 * A MARS handler is one file pasted into the MARS editor, with no require()
 * of other files. So each handler is bundled with esbuild into a single
 * script that defines `module.exports = (MARSModules) => ...` like the
 * hand-written handlers in apps/api/v2. The system prompt
 * (docs/planer-sistemski-prompt.md) is inlined as text at this step; a change
 * to the prompt needs a rebuild and a new paste of planner.POST.js.
 *
 * The bundle runs once when MARS loads the file, and the exported function
 * once per request, so module-level state (the in-memory cooldown) lasts as
 * long as MARS keeps the file loaded.
 *
 * Output is deterministic: same sources, byte-identical files. Works the same
 * under PowerShell (paths are joined with node:path).
 */
import { build } from 'esbuild';
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const API = join(ROOT, 'apps', 'api');
const PROMPT_FILE = join(ROOT, 'docs', 'planer-sistemski-prompt.md');

/** handler → output path under apps/api, and the route it serves. */
export const HANDLERS = [
  { entry: 'winter-destinations', out: 'v2/winter/destinations.GET.js', route: 'GET api/v2/winter/destinations' },
  { entry: 'planner-create', out: 'v2/planner.POST.js', route: 'POST api/v2/planner' },
  { entry: 'planner-plan', out: 'v2/planner/plan/_id.GET.js', route: 'GET api/v2/planner/plan/:id' },
  { entry: 'planner-swap', out: 'v2/planner/swap.POST.js', route: 'POST api/v2/planner/swap' },
  { entry: 'planner-feedback', out: 'v2/planner/feedback.POST.js', route: 'POST api/v2/planner/feedback' },
  { entry: 'planner-quota', out: 'v2/planner/quota.GET.js', route: 'GET api/v2/planner/quota' },
  { entry: 'planner-selftest', out: 'v2/planner/selftest.GET.js', route: 'GET api/v2/planner/selftest (admin)' },
  { entry: 'planner-candidates-export', out: 'v2/planner/candidates-export.GET.js', route: 'GET api/v2/planner/candidates-export (admin)' },
  { entry: 'planner-cleanup', out: 'v2/planner/cleanup.POST.js', route: 'POST api/v2/planner/cleanup (X-Cleanup-Token or admin)' },
  { entry: 'planner-cleanup-event', out: 'events/planner-cleanup.js', route: 'MARS scheduled event, once a day' },
];

/** lib/planner/system-prompt.js reads a file under Node; in the bundle it is the file's text. */
const inlineSystemPrompt = {
  name: 'inline-system-prompt',
  setup(pluginBuild) {
    pluginBuild.onLoad({ filter: /[\\/]lib[\\/]planner[\\/]system-prompt\.js$/ }, () => ({
      contents: `module.exports = ${JSON.stringify(readFileSync(PROMPT_FILE, 'utf8').replace(/\r\n/g, '\n').trim())};`,
      loader: 'js',
    }));
  },
};

async function bundle(handler) {
  const result = await build({
    entryPoints: [join(API, 'handlers', `${handler.entry}.js`)],
    bundle: true,
    write: false,
    format: 'iife',
    globalName: '__gspHandler',
    platform: 'neutral',
    mainFields: ['main'],
    target: 'es2019',
    charset: 'ascii',
    legalComments: 'none',
    logLevel: 'silent',
    plugins: [inlineSystemPrompt],
  });
  const code = result.outputFiles[0].text.replace(/\r\n/g, '\n').trimEnd();
  const marsName = handler.out.replace(/(^|\/)_([a-z]+)/g, '$1:$2');
  return [
    `// GENERATED by tools/build-mars-api.mjs from apps/api/handlers/${handler.entry}.js. Do not edit here:`,
    '// change the handler or apps/api/lib, run `node tools/build-mars-api.mjs`, paste the result into MARS.',
    `// Route: ${handler.route}`,
    marsName !== handler.out ? `// In the MARS editor this file is ${marsName} (Windows cannot have ":" in a file name).` : null,
    'module.exports = (function () {',
    code,
    '  return (MARSModules) => __gspHandler(MARSModules);',
    '})();',
    '',
  ]
    .filter((line) => line !== null)
    .join('\n');
}

async function main() {
  const check = process.argv.includes('--check');
  const stale = [];
  for (const handler of HANDLERS) {
    const target = join(API, ...handler.out.split('/'));
    const text = await bundle(handler);
    const current = existsSync(target) ? readFileSync(target, 'utf8').replace(/\r\n/g, '\n') : null;
    if (current === text) continue;
    if (check) {
      stale.push(relative(ROOT, target));
      continue;
    }
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, text);
    console.log(`wrote ${relative(ROOT, target)} (${Math.round(text.length / 1024)} KB)`);
  }
  if (check && stale.length) {
    console.error(`Stale MARS handlers, run node tools/build-mars-api.mjs:\n  ${stale.join('\n  ')}`);
    process.exit(2);
  }
  if (check) console.log('MARS handlers are up to date.');
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
